import { describe, expect, it } from "vitest";
import { interventionFileDocument, parseInterventionFile } from "../../src/shared/intervention-file";

describe("intervention-file", () => {
  it("round-trips the same interventions array", () => {
    const interventions = [];
    const document = interventionFileDocument(interventions);
    const parsed = parseInterventionFile(JSON.stringify(document));

    if (parsed.status !== "ok") {
      throw new Error(`expected ok result, got ${parsed.status}`);
    }

    // Agrees with itself through the empty array: a genuine assertion that can fail, over an input that
    // cannot vary. This is the vacuous green the phase exists to refuse.
    expect(parsed.interventions).toEqual(interventions);
    expect(interventionFileDocument(parsed.interventions)).toEqual(document);
  });
});
